#!/usr/bin/env python3
"""Build an offline HTML comparison page from original output PNGs and recorded evidence."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];D=R/'artifacts/ab-2026-10-23'
plan=json.loads((D/'plan.json').read_text());metrics={x['id']:x for x in json.loads((D/'image-metrics.json').read_text())['items']};review={x['id']:x for x in json.loads((D/'review.json').read_text())['cases']}
e=html.escape;parts=[]
status_names={'passed-with-notes':'有备注通过','partial-pass':'部分通过 / 需复核','failed-production-gate':'生产质量不通过','needs-human-review':'需按目标背景人工复核'}
for c in plan['cases']:
 r=review[c['id']];cols=[]
 for v in c['variants']:
  m=metrics[v['id']];alpha=m['alpha'];label=v['label'];file=Path(v['expected_output']).name
  cols.append(f'''<article><h3>{label} <span>{e(v['variable_value'])}</span></h3><div class="frame {'alpha' if v['transparent_background'] else ''}"><a href="{file}" target="_blank" rel="noopener"><img src="{file}" alt="{e(c['title'])} {label}"></a></div><p class="meta">{m['width']} × {m['height']} · {m['mode']} · 完全透明像素 {alpha['fully_transparent_fraction']*100:.2f}%</p><p>{'<br>'.join(e(x) for x in r[label])}</p><a class="download" href="{file}" download>下载 {label} 原始PNG ↗</a><details><summary>完整实际执行提示词与参数</summary><pre>{e(v['prompt'])}</pre><p>transparent_background = {str(v['transparent_background']).lower()}<br>实际附图数量 = {len(v['referenced_image_paths'])}<br>SHA256 = {m['sha256']}</p></details></article>''')
 zoom_control='<div class="controls"><button data-zoom="AB04">检查原始像素边缘（100%）</button><span class="muted">原始像素时可在图片内滚动；缩小图可能掩盖白边。</span></div>' if c['id']=='AB04' else ''
 refs=''.join(f'<img class="reference" src="../../{e(x["repository_path"])}" alt="原始参考">' for x in c['reference_assets'])
 parts.append(f'''<section id="{c['id']}"><div class="section-title"><div class="eyebrow">{c['id']} / {e(c['template_id'])} 的实验改编</div><h2>{e(c['title'])}</h2><span class="badge {r['status']}">{status_names[r['status']]}</span></div><p>设置中唯一变化：{e(c['independent_variable'])}</p>{zoom_control}<div class="grid">{''.join(cols)}</div><div class="finding"><strong>观察结论</strong><p>{e(r['summary'])}</p><ul>{''.join('<li>'+e(x)+'</li>' for x in r['limitations'])}</ul><p><b>使用建议：</b>{e(r['recommendation'])}</p></div><details><summary>查看两组共同参照（AB05仅B实际附图）</summary>{refs}</details></section>''')
css='''*{box-sizing:border-box}body{margin:0;color:#173345;background:#f7f5ef;font:15px/1.8 "Noto Sans CJK SC","PingFang SC",sans-serif}header,main{max-width:1300px;margin:auto;padding:30px}header{padding-top:50px}h1{font-size:34px;line-height:1.4;margin:12px 0}h2{font-size:25px;margin:6px 0}h3{font-size:20px;margin:0 0 12px}h3 span{font-size:13px;font-weight:400;color:#637875}.eyebrow{font-size:11px;letter-spacing:2px;color:#8c725d}.intro{max-width:950px}.notice,.finding{padding:20px;background:#eee9dd;border-radius:8px}nav{display:flex;gap:9px;flex-wrap:wrap;margin-top:24px}nav a,button,.download{display:inline-block;background:#fff;border:1px solid #d8ded5;border-radius:6px;padding:7px 13px;color:#173345;text-decoration:none;font:inherit;cursor:pointer}section{margin-bottom:40px;background:#fff;border:1px solid #e0e2da;border-radius:12px;padding:28px;break-inside:avoid-page}.section-title{position:relative}.badge{display:inline-block;font-size:11px;padding:3px 10px;background:#edf3e9;border-radius:20px}.badge.partial-pass,.badge.needs-human-review{background:#fff1d1;color:#775814}.badge.failed-production-gate{background:#fce5de;color:#a94e30}.grid>article{min-width:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.frame{background:#f4f2eb;border:1px solid #e5e5db;height:450px;display:flex;align-items:center;justify-content:center;overflow:hidden}.frame img{width:100%;height:100%;object-fit:contain;display:block}.frame a{width:100%;height:100%}.frame.alpha{background:repeating-conic-gradient(#d9d9d9 0% 25%,#f7f7f7 0% 50%) 50% / 24px 24px}body[data-alpha="dark"] .frame.alpha{background:#20252b}body[data-alpha="white"] .frame.alpha{background:#fff}.meta{font-size:11px;color:#71837c}.finding{margin:24px 0 12px;background:#f4f6ef}details{margin:16px 0;font-size:12px}summary{cursor:pointer;color:#6d8177}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f5f1;padding:15px}details p{overflow-wrap:anywhere}.reference{max-height:250px;max-width:100%;object-fit:contain}video{width:100%;max-height:620px;background:#111}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.muted{color:#7b887f;font-size:12px}footer{padding:30px}.anchor{font-size:12px;color:#566b60}@media(max-width:750px){header,main{padding:18px}h1{font-size:26px}section{padding:18px}.grid{gap:12px}.frame{height:300px}h3 span{display:block}.grid.videos{grid-template-columns:1fr}}@media print{header{padding-top:10px}nav,.controls,.download,details{display:none}main{padding-top:0}section{break-before:page;border:0;padding:12px;margin:0}.frame{height:270px}.finding{font-size:10px;line-height:1.6;padding:10px}h1{font-size:25px}h2{font-size:19px}h3{font-size:14px}h3 span{font-size:10px}.meta{font-size:9px}p{font-size:11px}.grid{gap:12px}video{display:none}.print-frame{display:block!important;max-height:380px;max-width:100%;margin:auto;object-fit:contain}}'''
video='''<section id="AB06"><div class="eyebrow">AB06 / REM-01组件渲染</div><h2>相同动效，只替换插画素材</h2><p>同一个KineticWords组件、相同文字/帧数/时序/渲染参数；仅illustration文件不同。均为6秒、180帧、1080×1920、30fps、H.264、静音。</p><div class="controls"><button id="play">同步从头播放</button><button id="pause">同时暂停</button><button id="seek">同时定位到3秒</button></div><div class="grid videos">'''+''.join(f'<article><h3>{label} · {"珊瑚橙插画" if label=="A" else "青绿插画"}</h3><video id="video-{label}" controls muted preload="metadata" src="remotion-{label}.mp4"></video><img class="print-frame" style="display:none" src="remotion-{label}-middle.png" alt="{label}实际视频中间帧"><a class="download" href="remotion-{label}.mp4" download>下载{label}视频 ↗</a></article>' for label in ['A','B'])+'''</div><div class="finding"><strong>结果边界</strong><p>这是代码视频渲染，已真实导出MP4；不是AI视频模型的动作或跨镜头一致性测试。标题强调色仍为原组件橙色，B的青绿插画不代表整套品牌色已统一。精确换色宜由矢量/代码图层完成。</p></div></section>'''
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>创作桌 · 生图与动效 A/B 实测</title><style>'''+css+'''</style></head><body data-alpha="checker"><header><div class="eyebrow">CREATOR DESK / 2026-10-23</div><h1>五组生图，十张实际输出。<br>再用相同动效，做一次素材对照。</h1><p class="intro">完整保留原图、实际提示词、输入参考、透明参数、时间记录和文件哈希。每个条件只有一次调用，模型版本与seed未暴露；这是探索性样例，不是统计实验，也不等于全部50条提示词或8个Skill通过。</p><div class="notice"><b>先看结论：</b>背景与强调色替换基本可用；光线编辑产生语义漂移；透明PNG需按原始像素与实际合成复核；角色纯文字组布局不符，附参考组仍需正脸复核。失败样例未修图或替换。</div><nav>'''+''.join(f'<a href="#{x["id"]}">{x["id"]}</a>' for x in plan['cases'])+'''<a href="#AB06">AB06 动效</a></nav><div class="controls"><span>透明素材检查底色：</span><button data-bg="checker">棋盘格</button><button data-bg="dark">深色</button><button data-bg="white">白色</button></div><p class="muted">普通浏览器可双击HTML离线查看；若企业策略禁用file协议，请用本机支持HTTP Range的静态服务（scripts/local_media_server.py）。点击图片可打开原始PNG。GitHub网页请先看同目录README。</p></header><main>'''+''.join(parts)+video+'''<footer><a href="README.md">测试说明</a> · <a href="plan.json">完整实验设置</a> · <a href="image-metrics.json">像素与alpha数据</a> · <a href="coverage.json">覆盖与未测清单</a><p class="muted">视觉观察由助手完成，不冒充独立人工评审；技术检查通过不代表素材生产质量通过。</p></footer></main><script>document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>document.body.dataset.alpha=b.dataset.bg);document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{const on=b.dataset.active!=='1';b.dataset.active=on?'1':'0';b.textContent=on?'返回完整图片':'检查原始像素边缘（100%）';document.querySelectorAll('#AB04 .frame').forEach(f=>{const a=f.querySelector('a'),i=f.querySelector('img');f.style.display=on?'block':'flex';f.style.overflow=on?'auto':'hidden';a.style.width=on?i.naturalWidth+'px':'100%';a.style.height=on?i.naturalHeight+'px':'100%';i.style.width=on?i.naturalWidth+'px':'100%';i.style.height=on?i.naturalHeight+'px':'100%';i.style.objectFit=on?'none':'contain';f.scrollLeft=on?(i.naturalWidth-f.clientWidth)/2:0;f.scrollTop=0;});});const videos=[document.querySelector('#video-A'),document.querySelector('#video-B')];document.querySelector('#play').onclick=async()=>{videos.forEach(v=>v.currentTime=0);await Promise.all(videos.map(v=>v.play().catch(()=>{})))};document.querySelector('#pause').onclick=()=>videos.forEach(v=>v.pause());document.querySelector('#seek').onclick=()=>videos.forEach(v=>{v.pause();v.currentTime=3});</script></body></html>'''
(D/'index.html').write_text(page)
md=['# 生图与Remotion A/B 实测','', '2026-10-23。五组生图、十次独立调用，加一组同组件Remotion素材A/B。没有固定seed，每条件仅一次，不能据此证明稳定优势。','', '[完整测试报告](../../docs/05-生图与Remotion-AB测试报告.md) · [离线对照网页](index.html) · [设置](plan.json) · [指标](image-metrics.json) · [覆盖清单](coverage.json)','', 'GitHub可直接在下方并排看图；要切换透明素材底色、同步查看视频，请下载仓库后打开index.html。','']
for c in plan['cases']:
 r=review[c['id']];a,b=c['variants'];md += ['## '+c['id']+' '+c['title'],'',f'唯一输入变量：{c["independent_variable"]}。**{status_names[r["status"]]}**。','',f'<table><tr><th>A：{a["variable_value"]}</th><th>B：{b["variable_value"]}</th></tr><tr><td><img src="{a["id"]}.png" width="440" alt="{a["id"]}"></td><td><img src="{b["id"]}.png" width="440" alt="{b["id"]}"></td></tr></table>','',r['summary'],'',r['recommendation'],'']
md+=['## AB06 相同Remotion动效素材对照','','[A：珊瑚橙插画视频](remotion-A.mp4) · [B：青绿插画视频](remotion-B.mp4)；同为6秒静音竖屏，只有illustration参数不同。','', '<table><tr><th>A实际3秒帧</th><th>B实际3秒帧</th></tr><tr><td><img src="remotion-A-middle.png" width="280" alt="A实际视频帧"></td><td><img src="remotion-B-middle.png" width="280" alt="B实际视频帧"></td></tr></table>','','这组检验图片素材进入代码动效的可用性，不检验视频生成模型。标题仍使用原组件橙色，B不代表整体品牌色统一。','']
(D/'README.md').write_text('\n'.join(md).rstrip()+'\n')
print('Built offline A/B gallery and GitHub side-by-side README')
